window.AUTH=window.AUTH||{};window.AUTH["22-210"]={"d":"22-210","id":"2022/22-210","n":"Dupree v. Younger","briefs":[{"k":"petitioner","label":"Brief of petitioner Neil Dupree","date":"2023-02-27","url":"https://www.supremecourt.gov/DocketPDF/22/22-210/255698/20230227171616191_Dupree--FINAL%20Brief%20for%20Petitioner%20-%20camera%20ready%2002-27-2023.pdf","side":"pet","n":106},{"k":"respondent","label":"Brief of respondent Kevin Younger","date":"2023-03-29","url":"https://www.supremecourt.gov/DocketPDF/22/22-210/260173/20230329131113091_Younger_Respondent%20Merits%20Brief_3.29.23.pdf","side":"res","n":59},{"k":"reply","label":"Reply of petitioner Neil Dupree","date":"2023-04-12","url":"https://www.supremecourt.gov/DocketPDF/22/22-210/263391/20230412182201035_Dupree--Reply%20-%20camera%20ready.pdf","side":"pet","n":24}],"opinion":"https://www.supremecourt.gov/opinions/22pdf/598us2r29_k5fm.pdf","tr":true,"items":[{"t":"case","label":"Anderson v. Liberty Lobby, Inc.","cite":"477 U.S. 242","y":1986,"id":"1985/84-1602","sc":1,"op":1,"sum":"In a 6-to-3 opinion, the Court held that the purpose of summary judgments is to determine if the evidence is so one-sided that a party should prevail as a matter of law. Summary judgments will not lie if there is a sufficient likelihood that a reasonable jury would return a verdict favorable to the nonmoving party.","sumSrc":"Oyez","by":{"0":"4-5","1":"21, 24"}},{"t":"case","label":"Baltimore & P. R. Co. v. Trustees of Sixth Presbyterian Church","cite":"91 U.S. 127","y":1875,"id":"scdb/1875-027","sc":1,"sum":"Affidavits, depositions, and matters of parol evidence, though appearing in, the transcript of the proceedings of a common-law court, do not form part of the record unless. they áre made so by an-agreed statement of facts, a bill of exceptions, a special verdict, op a demurrer to the evidence.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"22, 24, 27"}},{"t":"case","label":"Banuelos v. Constr. Laborers’ Tr. Funds for S. Cal.","cite":"382 F.3d 897","y":2004,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/382/897/","op":1,"by":{"0":"15, 33"}},{"t":"case","label":"Barton v. Auto. Ins. Co. of Hartford, Conn.","cite":"63 F.2d 631","y":1933,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.2d/63/631/","by":{"0":"20"}},{"t":"case","label":"Behrens v. Pelletier","cite":"516 U.S. 299","y":1996,"id":"1995/94-1244","sc":1,"sum":"The Court held that the court of appeals was not deprived of jurisdiction. The Court reasoned that the agent was not limited in such circumstances to one interlocutory appeal from a denial of qualified immunity.","sumSrc":"Oyez","by":{"0":"13, 19"}},{"t":"case","label":"Belk, Inc. v. Meyer Corp., U.S.","cite":"679 F.3d 146","y":2012,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/679/146/","sum":"Explaining that Rule 50 “is not concerned with pure questions of law that are detached from the evidence, not within the domain of the jury, and only ever properly ruled upon by the judge”.","sumSrc":"brief:0","by":{"0":"39","1":"26"}},{"t":"case","label":"Brown v. Allen","cite":"344 U.S. 443","y":1953,"id":"scdb/1952-043","sc":1,"sum":"1. Where, on direct review of his conviction, a state prisoner's claim of federal constitutional right has been decided adversely to him by the state supreme court and an application to this Court for certiorari has been denied, he has satisfied the requirement of 28 U. S. C. § 2254 that state remedies be exhausted before a federal court may grant an application for habeas corpus.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"case","label":"Burton v. E.I. du Pont de Nemours & Co.","cite":"994 F.3d 791","y":2021,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/994/791/","by":{"0":"30-31, 33"}},{"t":"case","label":"Cadle v. GEICO Gen. Ins. Co.","cite":"838 F.3d 1113","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/838/1113/","sum":"Explaining that in a Rule 50 motion, “only the sufficiency of the evidence matters” (quotation marks omitted).","sumSrc":"brief:0","by":{"0":"39","1":"26"}},{"t":"case","label":"Callaway Golf Co. v. Acushnet Co.","cite":"576 F.3d 1331","y":2009,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/576/1331/","by":{"0":"18"}},{"t":"case","label":"(iii) Cases—Continued Celotex Corp. v. Catrett","cite":"477 U.S. 317","y":1986,"id":"1985/85-198","sc":1,"ar":1,"sum":"In September 1980, respondent administratrix filed this wrongful-death action in Federal District Court, alleging that her husband's death in 1979 resulted from his exposure to asbestos products manufactured or distributed by the defendants, who included petitioner corporation. In September 1981, petitioner filed a motion for summary judgment, asserting that during discovery respondent failed to produce any evidence …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5","2":"8"}},{"t":"case","label":"Chemetall GMBH v. ZR Energy, Inc.","cite":"320 F.3d 714","y":2003,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/320/714/","op":1,"by":{"0":"15, 16, 36"}},{"t":"case","label":"Ciralsky v. CIA","cite":"355 F.3d 661","y":2004,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/355/661/","by":{"0":"14"}},{"t":"case","label":"Cohen v. Beneficial Indus. Loan Corp.","cite":"337 U.S. 541","y":1949,"id":"scdb/1948-101","sc":1,"sum":"1. Under 28 U. S. C. § 1291, appeal may be. taken from an order of a Federal District Court denying a corporation's motion that the plaintiff in a stockholder's derivative action be required, pursuant to a state statute, to give security for reasonable expenses of the defendants, in connection with the action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"15","2":"4"}},{"t":"case","label":"Cone v. West Virginia Pulp & Paper Co.","cite":"330 U.S. 212","y":1947,"id":"scdb/1946-056","sc":1,"op":1,"sum":"Where a party whose motion for a directed verdict has been denied in a federal district court fails, within 10 days after reception of a verdict against him, to make a motion for judgment notwithstanding the verdict, as authorized by Rule 50 (b) of the Federal Rules of Civil Procedure, an appellate court is precluded from directing entry of such a judgment. Pp. 217-218. 153 F. 2d 576, reversed. Petitioner sued …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 43","1":"22, 27"}},{"t":"case","label":"Cribari v. Allstate Fire & Cas. Ins. Co.","cite":"861 F. App’x 693","y":2021,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/861/693/","by":{"0":"33"}},{"t":"case","label":"Cuozzo Speed Techs., LLC v. Lee","cite":"579 U.S. 261","y":2016,"id":"2015/15-446","sc":1,"sum":"The Court held that the Patent Trial and Appeal Board may apply the broadest reasonable interpretation of patent claims during an inter partes review proceeding, and such a proceeding is not judicially reviewable.","sumSrc":"Oyez","by":{"0":"14"}},{"t":"case","label":"DeSilva v. DiLeonardi","cite":"181 F.3d 865","y":1999,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/181/865/","by":{"0":"36-37","1":"40"}},{"t":"case","label":"Estate of Diaz v. City of Anaheim","cite":"840 F.3d 592","y":2016,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/840/592/","by":{"0":"18","1":"30"}},{"t":"case","label":"Digit. Equip. Corp. v. Desktop Direct, Inc.","cite":"511 U.S. 863","y":1994,"id":"1993/93-405","sc":1,"sum":"The Supreme Court ruled that the denial of immunity - while cause for concern - does not automatically create a right to immediate appeal. It is important to have final judgments before appeals are made, Justice David H. Souter wrote for the Court, and exceptions should only be made in particularly important cases.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"ePlus, Inc. v. Lawson Software, Inc.","cite":"700 F.3d 509","y":2012,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/700/509/","by":{"0":"35"}},{"t":"case","label":"Ericsson Inc. v. TCL Commc’n Techn. Holdings Ltd.","cite":"955 F.3d 1317","y":2020,"court":"Fed. Cir.","url":"https://www.courtlistener.com/c/F.3d/955/1317/","by":{"0":"15, 34"}},{"t":"case","label":"Escriba v. Foster Poultry Farms, Inc.","cite":"743 F.3d 1236","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/743/1236/","by":{"0":"33"}},{"t":"case","label":"F.B.T. Prods., LLC v. Aftermath Recs.","cite":"621 F.3d 958","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/621/958/","by":{"0":"33"}},{"t":"case","label":"Feld v. Feld","cite":"688 F.3d 779","y":2012,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/688/779/","op":5,"by":{"0":"15, 33, 36","1":"43"}},{"t":"case","label":"First City Bank, N.A. v. Air Capitol Aircraft Sales, Inc.","cite":"820 F.2d 1127","y":1987,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.2d/820/1127/","op":1,"ar":1,"by":{"0":"17","1":"30-31"}},{"t":"case","label":"Foman v. Davis","cite":"371 U.S. 178","y":1962,"id":"1962/41","sc":1,"sum":"A Federal District Court dismissed petitioner's complaint in a civil action for failure to state a claim upon which relief might be granted. Petitioner promptly moved to vacate the judgment and amend the complaint so as to state an alternative theory for recovery. Before the Court ruled on those motions, petitioner filed notice of appeal from the judgment of dismissal. Subsequently, the District Court denied the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Frank C. Pollara Grp., LLC v. Ocean View Inv. Holding, LLC","cite":"784 F.3d 177","y":2015,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/784/177/","op":1,"by":{"0":"15, 35"}},{"t":"case","label":"Fratta v. Grace Line, Inc.","cite":"139 F.2d 743","y":1943,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/139/743/","by":{"0":"41"}},{"t":"case","label":"Galloway v. United States","cite":"319 U.S. 372","y":1943,"id":"scdb/1942-050","sc":1,"sum":"1. In this suit against the United States to recover benefits under a contract of war risk insurance, on account of alleged total and permanent disability resulting from insanity of the insured while the policy was in force, held that the evidence was insufficient to support a judgment for the plaintiff and the trial court properly granted the Government's motion for a directed verdict.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"39"}},{"t":"case","label":"Globe Liquor Co., Inc. v. San Roman et al.","cite":"160 F.2d 800","y":1947,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/160/800/","by":{"0":"43"}},{"t":"case","label":"Globe Liquor Co. v. San Roman","cite":"332 U.S. 571","y":1948,"id":"scdb/1947-019","sc":1,"sum":"In a -suit on a contract in a Federal District Court, each party moved for 9 directed verdici. One party's motion was granted and judgment was entered for him. The other party failed to move as authorized by Rule 50 (b) of the Federal Rules of Civil Procedure to have the judgment set aside and judgment entered in accordance with his own motion for a directed verdict. The Circuit Court of Appeals reversed and …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"42, 43","1":"27"}},{"t":"case","label":"Gloria Steamship Co. v. Smith","cite":"376 F.2d 46","y":1967,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/376/46/","by":{"0":"13"}},{"t":"case","label":"GN Netcom, Inc. v. Plantronics, Inc.","cite":"930 F.3d 76","y":2019,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/930/76/","by":{"0":"17","1":"29"}},{"t":"case","label":"Graham Cnty. Soil & Water Conservation Dist. v. United States ex rel. Wilson","cite":"545 U.S. 409","y":2005,"id":"2004/04-169","sc":1,"sum":"The Court ruled that the six-year statute of limitations did not apply to suits for retaliation. The majority opinion by Justice Clarence Thomas found the statute of limitations \"ambiguous.\" The ambiguity arose from the fact that the six-year limitation in the FCA starts from the time the false claim was made. Yet in a retaliation suit, no actual false claim needs to be alleged.","sumSrc":"Oyez","by":{"0":"31"}},{"t":"case","label":"Graham v. John Deere Co. of Kansas City","cite":"383 U.S. 1","y":1966,"id":"1965/11","sc":1,"sum":"The Court held that the Patent Act of 1952 did not lower the standards required for the patentability of an invention by adding an inquiry into obviousness to the statutory requirements of novelty and utility.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Gramercy Mills, Inc. v. Wolens","cite":"63 F.3d 569","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/63/569/","by":{"0":"17, 30, 31","1":"30"}},{"t":"case","label":"Hampton v. City of Chicago","cite":"643 F.2d 478","y":1981,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/643/478/","by":{"0":"14"}},{"t":"case","label":"HK Sys., Inc. v. Eaton Corp.","cite":"553 F.3d 1086","y":2009,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/553/1086/","by":{"0":"31"}},{"t":"case","label":"Ji v. Bose Corp.","cite":"626 F.3d 116","y":2010,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/626/116/","op":1,"by":{"0":"36"}},{"t":"case","label":"Johnson v. Jones","cite":"515 U.S. 304","y":1995,"id":"1994/94-455","sc":1,"sum":"The Court held that a defendant, who is entitled to invoke a qualified immunity defense, may not appeal a District Court's summary judgment order insofar as that order determines whether or not the pretrial record sets forth a genuine issue of fact for trial.","sumSrc":"Oyez","by":{"0":"4, 19"}},{"t":"case","label":"Johnson v. New York, N.H. & H.R. Co.","cite":"194 F.2d 194","y":1952,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/194/194/","by":{"0":"43"}},{"t":"case","label":"Johnson v. New York, N.H. & H.R. Co.","cite":"344 U.S. 48","y":1952,"id":"scdb/1952-009","sc":1,"sum":"Under Rule 50 (b) of the Federal Rules of Civil Procedure, the Court of Appeals could not direct entry of a judgment for defendant notwithstanding the verdict.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27, 29, 30, 42, 43","1":"26-27"}},{"t":"case","label":"Kay v. United of Omaha Life Ins. Co.","cite":"562 F. App’x 380","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/562/380/","by":{"0":"33"}},{"t":"case","label":"Kidis v. Reid","cite":"976 F.3d 708","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/976/708/","by":{"0":"33"}},{"t":"case","label":"Krauss Bros. Lumber Co. v. Mellon","cite":"276 U.S. 386","y":1928,"id":"scdb/1927-065","sc":1,"sum":"Exhibits sent by the trial court to the reviewing court may be identified and made part of the bill of exceptions by appropriate reference in the bill itself. P. 391. 18 F. (2d) 369, reversed. CERTIORARI, 275 U. S. 513, to a judgment of the Circuit Court of Appeals, which affirmed the judgment of the District Court in an action on a reparation order made by the Interstate Commerce Commission. The court below refused …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"21"}},{"t":"case","label":"Kurowski v. Krajewski","cite":"848 F.2d 767","y":1988,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/848/767/","by":{"0":"13"}},{"t":"case","label":"Laverett v. Cont’l Briar Pipe Co.","cite":"25 F. Supp. 80","y":1938,"court":"E.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp./25/80/","by":{"0":"28"}},{"t":"case","label":"Lewis v. Rego Co.","cite":"757 F.2d 66","y":1985,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.2d/757/66/","by":{"0":"17","1":"30"}},{"t":"case","label":"Lexington Ins. Co. v. Horace Mann Ins. Co.","cite":"861 F.3d 661","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/861/661/","sum":"Explaining that “as a general matter, pure questions of law ought not to be included in a Rule 50(a) motion in the first place, as doing so ‘defeat[s the] purpose [of that motion], which is to challenge the sufficiency of the evidence’” (alterations in original) (citation omitted).","sumSrc":"brief:0","by":{"0":"39","1":"26"}},{"t":"case","label":"Markman v. Westview Instruments, Inc.","cite":"517 U.S. 370","y":1996,"id":"1995/95-26","sc":1,"op":1,"sum":"Authored by Justice David H. Souter, the Court held that the construction of a patent, including terms of art within its claim, is exclusively within the province of the court. Justice Souter wrote that \"judges, not juries, are the better suited to find the acquired meaning of patent terms.\".","sumSrc":"Oyez","by":{"0":"34","1":"30"}},{"t":"case","label":"Matsushita Elec. Indus. Co. v. Zenith Radio Corp.","cite":"475 U.S. 574","y":1986,"id":"1985/83-2004","sc":1,"sum":"The Court held that evidence of alleged conspiracies is not sufficient to prove allegations of violating antitrust legislation unless there is evidence that the conspiracies in question injured American companies.","sumSrc":"Oyez","by":{"0":"26"}},{"t":"case","label":"Microsoft Corp. v. Baker","cite":"137 S. Ct. 1702","y":2017,"id":"2016/15-457","sc":1,"sum":"The Court determined that the federal courts of appeals lack jurisdiction to review an order denying class certification after the named plaintiffs have voluntarily dismissed their claims with prejudice.","sumSrc":"Oyez","by":{"0":"13"}},{"t":"case","label":"Mitchell v. Forsyth","cite":"472 U.S. 511","y":1985,"id":"1984/84-335","sc":1,"op":1,"sum":"In 1970, petitioner, who was then the Attorney General, authorized a warrantless wiretap for the purpose of gathering intelligence regarding the activities of a radical group that had made tentative plans to take actions threatening the Nation's security. During the time the wiretap was installed, the Government intercepted three conversations between a member of the group and respondent. Thereafter, this Court in …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19","1":"44"}},{"t":"case","label":"Mohawk Indus., Inc. v. Carpenter","cite":"558 U.S. 100","y":2009,"id":"2009/08-678","sc":1,"sum":"The Court held that disclosure orders adverse to attorney-client privilege do not qualify for immediate appeal under the collateral order doctrine.","sumSrc":"Oyez","by":{"0":"13, 18","1":"29","2":"4"}},{"t":"case","label":"Montgomery Ward & Co. v. Duncan","cite":"311 U.S. 243","y":1940,"id":"scdb/1940-039","sc":1,"sum":"1. A defendant who moved the District Court successfully for judgment non obstante veredicto and who thereupon urged that, because of the granting of the judgment his alternative motion (on other grounds) for a new trial had passed out of the case, did not thereby elect to stand upon his motion for judgment alone and abandon his right to have the motion for new trial decided by the District Court should his judgment …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"41"}},{"t":"case","label":"Nalle v. Oyster","cite":"230 U.S. 165","y":1913,"id":"scdb/1912-276","sc":1,"sum":"This practice was not modified by the Code, nor has it been by any rules of practice established under it; there is no provision giving the right to take exceptions on rulings other than those made in the course of the trial, except-as based on tbé Statute of Westminster; nor does any rule of court require an exception to be taken in order to preserve rights of a plaintiff against whose declaration a demurrer has …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"21, 22, 23"}},{"t":"case","label":"New York Marine and General Ins. Co. v. Continental Cement","cite":"761 F.3d 838","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/761/838/","by":{"0":"31, 32"}},{"t":"case","label":"Nixon v. Fitzgerald","cite":"457 U.S. 731","y":1982,"id":"1981/79-1738","sc":1,"sum":"The Court held that the President \"is entitled to absolute immunity from damages liability predicated on his official acts.\" This sweeping immunity, argued Justice Powell, was a function of the \"President's unique office, rooted in the constitutional tradition of separation of powers and supported by our history.\".","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Nolfi v. Ohio Kentucky Oil Corp.","cite":"675 F.3d 538","y":2012,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/675/538/","by":{"0":"33"}},{"t":"case","label":"Oklahoma v. Castro-Huerta","cite":"142 S. Ct. 2486","y":2022,"id":"2021/21-429","sc":1,"sum":"The Federal Government and the State have concurrent jurisdiction to prosecute crimes committed by non-Indians against Indians in Indian country.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"25"}},{"t":"case","label":"Ortiz v. Jordan","cite":"562 U.S. 180","y":2011,"id":"2010/09-737","sc":1,"op":10,"ar":5,"sum":"The Court held that a party may not appeal a denial of summary judgement after a district court has conducted a full trial on the merits.","sumSrc":"Oyez","by":{"0":"4, 5, 16, 39","1":"35","2":"2, 5, 17"}},{"t":"case","label":"Parklane Hosiery Co. v. Shore","cite":"439 U.S. 322","y":1979,"id":"1978/77-1305","sc":1,"sum":"Respondent brought this stockholder's class action in the District Court for damages and other relief against petitioners, a corporation, its officers, directors, and stockholders, who allegedly had issued a materially false and misleading proxy statement in violation of the federal securities laws and Securities and Exchange Commission (SEC) regulations. Before the action came to trial the SEC sued the same …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"22, 26, 27"}},{"t":"case","label":"Paschal v. Flagstar Bank","cite":"295 F.3d 565","y":2002,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/295/565/","by":{"0":"32","1":"17"}},{"t":"case","label":"Pavon v. Swift Transp. Co.","cite":"192 F.3d 902","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/192/902/","by":{"0":"32"}},{"t":"case","label":"Pepper v. United States","cite":"562 U.S. 476","y":2011,"id":"2010/09-6822","sc":1,"op":6,"sum":"The Court held that when a defendant's sentence has been set aside on appeal, a district court may consider evidence of the defendant's rehabilitation after the initial sentences, which may support lesser sentencing guidelines.","sumSrc":"Oyez","by":{"0":"31","1":"28","2":"5"}},{"t":"case","label":"Petrella v. Metro-Goldwyn-Mayer, Inc.","cite":"572 U.S. 663","y":2014,"id":"2013/12-1315","sc":1,"sum":"The Court held that the doctrine of laches could not be used to prevent a copyright suit that seeks relief for damages that occurred within the three-year window allowed by the Copyright Act.","sumSrc":"Oyez","by":{"0":"31-32"}},{"t":"case","label":"Porter v. AAR Aircraft Servs., Inc.","cite":"790 F. App’x 708","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/790/708/","by":{"0":"33"}},{"t":"case","label":"Puerto Rico Aqueduct & Sewer Auth. v. Metcalf & Eddy, Inc.","cite":"506 U.S. 139","y":1993,"id":"1992/91-1010","sc":1,"sum":"States and state entities that claim to be \"arms of the State\" may take advantage of the collateral order doctrine of Cohen v. Beneficial Industrial Loan Corp., 337 U. S. 541, to appeal a district court order denying a claim of Eleventh Amendment immunity from suit in federal court. Although 28 U. S. C. § 1291 requires that appeals be taken from \"final decisions of the district courts,\" Cohen, supra, at 546, …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 19"}},{"t":"case","label":"Quackenbush v. Allstate Ins. Co.","cite":"517 U.S. 706","y":1996,"id":"1995/95-244","sc":1,"op":2,"sum":"The Court held that an abstention-based remand order is appealable because the \"remand order here falls within that narrow class of collateral orders that are immediately appealable.\" Further, the Court held that the \"federal courts have the power to dismiss or remand cases based on abstention principles only where the relief sought is equitable or otherwise discretionary,\" and because \"this was a damages action, the District Court's remand order was an unwarranted application of the Burford doctrine.\" Justices Antonin Scalia and Anthony M. Kennedy wrote concurring opinions.","sumSrc":"Oyez","by":{"0":"11, 13","1":"28","2":"4"}},{"t":"case","label":"Rekhi v. Wildwood Indus., Inc.","cite":"61 F.3d 1313","y":1995,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/61/1313/","by":{"0":"32"}},{"t":"case","label":"Richardson-Merrell, Inc. v. Koller","cite":"472 U.S. 424","y":1985,"id":"1984/84-127","sc":1,"op":1,"sum":"Noting that some errors in interlocutory orders “go uncorrected until the appeal of a fnal judgment”.","sumSrc":"opinion","by":{"0":"17","1":"29"}},{"t":"case","label":"Rosario v. Livaditis","cite":"963 F.2d 1013","y":1992,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/963/1013/","by":{"0":"18","1":"30"}},{"t":"case","label":"Rose v. Uniroyal Goodrich Tire Co.","cite":"219 F.3d 1216","y":2000,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/219/1216/","by":{"0":"33"}},{"t":"case","label":"Ruyle v. Cont’l Oil Co.","cite":"44 F.3d 837","y":1994,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/44/837/","sum":"Explaining that Rule 50 motions “challenge the sufficiency of the evidence rather than the correctness of questions of law”.","sumSrc":"brief:0","by":{"0":"32, 40","1":"26, 43"}},{"t":"case","label":"Schiavone v. Fortune","cite":"477 U.S. 21","y":1986,"id":"1985/84-1839","sc":1,"sum":"The actions were properly dismissed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Scott v. Harris","cite":"550 U.S. 372","y":2007,"id":"2006/05-1631","sc":1,"sum":"The Court ruled 8-1 that Scott's actions were reasonable under the Fourth Amendment. The opinion by Justice Antonin Scalia relied heavily on a videotape of the car chase, which it said contradicted the plaintiff's claim that he was driving responsibly even while being pursued by the police.","sumSrc":"Oyez","by":{"0":"5"}},{"t":"case","label":"Shaw v. Edward Hines Lumber Co.","cite":"249 F.2d 434","y":1957,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.2d/249/434/","by":{"0":"40"}},{"t":"case","label":"Slocum v. New York Life Ins. Co.","cite":"228 U.S. 364","y":1913,"id":"scdb/1912-171","sc":1,"sum":"Where a life insurance policy plainly provides for payment of the stipulated premium within a specified period of grace after the due day and as plainly excludes any idea of partial payments distributed between the premium dates, the insured gains nothing by giving an agent a portion of the premium in the absence of authority given him by the company to accept it.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"27"}},{"t":"case","label":"Stampf v. Long Island R.R. Co.","cite":"761 F.3d 192","y":2014,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/761/192/","by":{"0":"15"}},{"t":"case","label":"Surrowitz v. Hilton Hotels Corp.","cite":"383 U.S. 363","y":1966,"id":"1965/161","sc":1,"sum":"PgahttAwaecplaenhhRatRaaccniafthxnopasrnaetcfaooiduuahipmdtasiptdttmroidlliicilteDopeenoonapatapltpnnbpoivnnnvsalhicslrleaoers2eesniaoea1aaaltito3tstrtg1cmiisnlrtibotit,fenalte,uiiomtnyy(ifoecfatdaobtiaon\"fotnnheegio)fnnrnobwp'dnesensrCmeosoefterste,tahrtofcooihheshs'ettogscftboasppdueahhtehonfkhyhmdloereefsertifohtevaairinnhmFcpcghwofliggdoafotledofsenialifaherpelimuodmrldfiealdlodiisonstaegrednecnasmhu'p,eutgrarhr …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Switzerland Cheese Ass’n v. E. Horne’s Mkt., Inc.","cite":"385 U.S. 23","y":1966,"id":"1966/42","sc":1,"sum":"Since the denial of the motion for summary* judgment related only to pretrial procedures and not to the merits, it was not \"interlocutory\" and therefore not appealable under § 1292 (a) (1). 351 F. 2d 552, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"5, 16","1":"15, 19, 28"}},{"t":"case","label":"Teal v. Walker","cite":"111 U.S. 242","y":1884,"id":"scdb/1883-215","sc":1,"sum":"Mortgage — Pleading.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"20, 23, 24","2":"11, 12"}},{"t":"case","label":"Tidewater Oil Co. v. United States","cite":"409 U.S. 151","y":1972,"id":"1972/71-366","sc":1,"sum":"The Expediting Act, providing that in a civil antitrust action brought by the United States in a federal district court an appeal from that court's final judgment will lie only to this Court, lodged exclusive appellate jurisdiction over such actions in this Court and thus bars the courts of appeals from asserting jurisdiction over interlocutory orders covered by 28 U. S. C. § 1292 (b), as well as over other …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25"}},{"t":"case","label":"TVT Recs. v. Island Def Jam Music Grp.","cite":"412 F.3d 82","y":2005,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/412/82/","by":{"0":"35"}},{"t":"case","label":"Unitherm Food Sys., Inc. v. Swift-Eckrich, Inc.","cite":"546 U.S. 394","y":2006,"id":"2005/04-597","sc":1,"op":1,"sum":"The Court ruled that a party must renew its motion for judgment under Rule 50(b) if the motion is to be the basis for an appeal.","sumSrc":"Oyez","by":{"0":"42, 43","1":"3, 15-16, 18, 22, 27, 37, 39, 45-46","2":"9"}},{"t":"case","label":"Varghese v. Honeywell Int’l, Inc.","cite":"424 F.3d 411","y":2005,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/424/411/","op":2,"by":{"0":"16, 33, 36"}},{"t":"case","label":"Weisgram v. Marley Co.","cite":"528 U.S. 440","y":2000,"id":"1999/99-161","sc":1,"sum":"The Court held that Federal Rule of Civil Procedure 50 permits an appellate court to direct the entry of judgment as a matter of law when it determines that evidence was erroneously admitted at trial and that the remaining, properly admitted, evidence is insufficient to constitute a submissible case.","sumSrc":"Oyez","by":{"0":"41"}},{"t":"case","label":"West Virginia Pulp & Paper Co. v. Cone","cite":"153 F.2d 576","y":1946,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/153/576/","by":{"0":"43"}},{"t":"case","label":"White Consol. Indus., Inc. v. McGill Mfg. Co.","cite":"165 F.3d 1185","y":1999,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/165/1185/","by":{"0":"33"}},{"t":"case","label":"Will v. Hallock","cite":"546 U.S. 345","y":2006,"id":"2005/04-1332","sc":1,"sum":"The Court ruled that the Circuit Court had no jurisdiction to hear an appeal under the collateral order doctrine. Writing for the Court, Justice David Souter stressed the narrow scope of the doctrine. The Court reiterated that only orders that cannot be \"effectively\" reviewed after a final judgment can be appealed before the close of the trial.","sumSrc":"Oyez","by":{"0":"18"}},{"t":"case","label":"Wolfgang v. Mid-Am. Motorsports, Inc.","cite":"111 F.3d 1515","y":1997,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/111/1515/","op":1,"by":{"0":"15"}},{"t":"const","label":"Amendment VII","clauses":[["seventh-amendment","Seventh Amendment (Civil Jury)"]],"text":"In Suits at common law, where the value in controversy shall exceed twenty dollars, the right of trial by jury shall be preserved, and no fact tried by a jury, shall be otherwise re-examined in any Court of the United States, than according to the rules of the common law.","by":{"0":"2, 3, 38, 40"}},{"t":"usc","label":"28 U.S.C. § 861a","url":"https://www.law.cornell.edu/uscode/text/28/861a","by":{"0":"25"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1291","url":"https://www.law.cornell.edu/uscode/text/28/1291","stext":{"head":"§1291. Final decisions of district courts","paras":[[0,"The courts of appeals (other than the United States Court of Appeals for the Federal Circuit) shall have jurisdiction of appeals from all final decisions of the district courts of the United States, the United States District Court for the District of the Canal Zone, the District Court of Guam, and the District Court of the Virgin Islands, except where a direct review may be had in the Supreme Court. The jurisdiction of the United States Court of Appeals for the Federal Circuit shall be limited to the jurisdiction described in sections 1292(c) and (d) and 1295 of this title."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1291?type=usc&year=mostrecent&link-type=html"},"op":4,"head":"§1291. Final decisions of district courts","tname":"Judiciary and Judicial Procedure","by":{"0":"2, 24-25","1":"1, 11, 14-17, 28","2":"2"}},{"t":"usc","label":"42 U.S.C. § 1997e","url":"https://www.law.cornell.edu/uscode/text/42/1997e","subs":["(a)"],"stext":{"head":"§1997e. Suits by prisoners","paras":[[0,"(a) Applicability of administrative remedies"],[0,"No action shall be brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility until such administrative remedies as are available are exhausted."],[0,"(b) Failure of State to adopt or adhere to administrative grievance procedure"],[0,"The failure of a State to adopt or adhere to an administrative grievance procedure shall not constitute the basis for an action under section 1997a or 1997c of this title."],[0,"(c) Dismissal"],[0,"(1) The court shall on its own motion or on the motion of a party dismiss any action brought with respect to prison conditions under section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility if the court is satisfied that the action is frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief."],[0,"(2) In the event that a claim is, on its face, frivolous, malicious, fails to state a claim upon which relief can be granted, or seeks monetary relief from a defendant who is immune from such relief, the court may dismiss the underlying claim without first requiring the exhaustion of administrative remedies."],[0,"(d) Attorney's fees"],[0,"(1) In any action brought by a prisoner who is confined to any jail, prison, or other correctional facility, in which attorney's fees are authorized under section 1988 1 of this title, such fees shall not be awarded, except to the extent that—"],[1,"(A) the fee was directly and reasonably incurred in proving an actual violation of the plaintiff's rights protected by a statute pursuant to which a fee may be awarded under section 1988 1 of this title; and"],[1,"(B)(i) the amount of the fee is proportionately related to the court ordered relief for the violation; or"],[1,"(ii) the fee was directly and reasonably incurred in enforcing the relief ordered for the violation."],[0,"(2) Whenever a monetary judgment is awarded in an action described in paragraph (1), a portion of the judgment (not to exceed 25 percent) shall be applied to satisfy the amount of attorney's fees awarded against the defendant. If the award of attorney's fees is not greater than 150 percent of the judgment, the excess shall be paid by the defendant."],[0,"(3) No award of attorney's fees in an action described in paragraph (1) shall be based on an hourly rate greater than 150 percent of the hourly rate established under section 3006A of title 18 for payment of court-appointed counsel."],[0,"(4) Nothing in this subsection shall prohibit a prisoner from entering into an agreement to pay an attorney's fee in an amount greater than the amount authorized under this subsection, if the fee is paid by the individual rather than by the defendant pursuant to section 1988 1 of this title."],[0,"(e) Limitation on recovery"],[0,"No Federal civil action may be brought by a prisoner confined in a jail, prison, or other correctional facility, for mental or emotional injury suffered while in custody without a prior showing of physical injury or the commission of a sexual act (as defined in section 2246 of title 18)."],[0,"(f) Hearings"],[0,"(1) To the extent practicable, in any action brought with respect to prison conditions in Federal court pursuant to section 1983 of this title, or any other Federal law, by a prisoner confined in any jail, prison, or other correctional facility, pretrial proceedings in which the prisoner's participation is required or permitted shall be conducted by telephone, video conference, or other telecommunications technology without removing the prisoner from the facility in which the prisoner is confined."],[0,"(2) Subject to the agreement of the official of the Federal, State, or local unit of government with custody over the prisoner, hearings may be conducted at the facility in which the prisoner is confined. To the extent practicable, the court shall allow counsel to participate by telephone, video conference, or other communications technology in any hearing held at the facility."],[0,"(g) Waiver of reply"],[0,"(1) Any defendant may waive the right to reply to any action brought by a prisoner confined in any jail, prison, or other correctional facility under section 1983 of this title or any other Federal law. Notwithstanding any other law or rule of procedure, such waiver shall not constitute an admission of the allegations contained in the complaint. No relief shall be granted to the plaintiff unless a reply has been filed."],[0,"(2) The court may require any defendant to reply to a complaint brought under this section if it finds that the plaintiff has a reasonable opportunity to prevail on the merits."],[0,"(h) \"Prisoner\" defined"],[0,"As used in this section, the term \"prisoner\" means any person incarcerated or detained in any facility who is accused of, convicted of, sentenced for, or adjudicated delinquent for, violations of criminal law or the terms and conditions of parole, probation, pretrial release, or diversionary program."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1997e?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1997e. Suits by prisoners","tname":"The Public Health and Welfare","by":{"0":"2, 7","1":"7, 20, 7","2":"1"}},{"t":"rule","label":"Fed. R. Civ. P. 46","url":"https://www.law.cornell.edu/rules/frcp/rule_46","by":{"0":"2, 28"}},{"t":"rule","label":"Fed. R. Civ. P. 50","url":"https://www.law.cornell.edu/rules/frcp/rule_50","subs":["(a)","(a)(1)","(a)(2)","(b)"],"by":{"0":"2, 3, 5, 38, 39, 41, 5, 6, 38, 39, 41, 6, 38, 38, 6, 38"}},{"t":"rule","label":"Fed. R. Civ. P. 52","url":"https://www.law.cornell.edu/rules/frcp/rule_52","subs":["(c)"],"by":{"0":"5"}},{"t":"rule","label":"Fed. R. Civ. P. 56","url":"https://www.law.cornell.edu/rules/frcp/rule_56","subs":["(a)"],"by":{"0":"2, 4, 4, 5","2":"8"}},{"t":"case","label":"Albino v. Baca","cite":"747 F.3d 1162","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/747/1162/","by":{"1":"20"}},{"t":"case","label":"Allen v. Harwood","cite":"728 F. App’x 222","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/728/222/","by":{"1":"20"}},{"t":"case","label":"Balt. & Carolina Line, Inc. v. Redman","cite":"295 U.S. 654","y":1935,"id":"scdb/1934-135","sc":1,"sum":"that in reversing because as a matter of law the evidence was insufficient to sustain the -Tekdict, the judgment of the Circuit Court of Appeals should embody a direction for a judgment of dismissal on the merits, and not for a new trial; and that such judgment of dismissal would be thp equivalent of a judgment for the defendant on a verdict directed in its favor.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"26"}},{"t":"case","label":"Bennett v. Pippin","cite":"74 F.3d 578","y":1996,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/74/578/","by":{"1":"31"}},{"t":"case","label":"ClearOne Commc’ns, Inc. v. Biamp Sys.","cite":"653 F.3d 1163","y":2011,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/653/1163/","by":{"1":"31"}},{"t":"case","label":"Dietz v. Bouldin","cite":"579 U.S. 40","y":2016,"id":"2015/15-458","sc":1,"sum":"The Court determined that a federal district court judge has some ability to recall jurors in a civil case after identifying an error in their verdict, subject to certain limitations to ensure the jurors were not prejudiced.","sumSrc":"Oyez","by":{"1":"28"}},{"t":"case","label":"Dunn, McCormack & MacPherson v. Connolly","cite":"708 S.E.2d 867","y":2011,"court":"Va.","url":"https://www.courtlistener.com/c/S.E.2d/708/867/","by":{"1":"35"}},{"t":"case","label":"Fisher v. Sun Underwriters Ins. Co.","cite":"179 A. 702","y":1935,"court":"R.I.","url":"https://www.courtlistener.com/c/A./179/702/","by":{"1":"33-34","2":"12, 13"}},{"t":"case","label":"Fountain v. Filson","cite":"336 U.S. 681","y":1949,"id":"scdb/1948-066","sc":1,"sum":"The Court of Appeals erred in directing entry of a personal money judgment and in thus depriving petitioner of an opportunity to dispute the facts material to that claim. Pp. 681-683. 84 U. S. App. D. C. -, 171 F. 2d 999, reversed. On appeal from a summary judgment of a district court denying a declaration of a resulting trust in realty, the Court of Appeals sustained this action but remanded the case to the …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"46"}},{"t":"case","label":"Granfinanciera, S.A. v. Nordberg","cite":"492 U.S. 33","y":1989,"id":"1988/87-1716","sc":1,"sum":"The Court held that the Seventh Amendment protected the right to a trial by jury in all cases in which a legal right, as opposed to an equitable right, was at issue.","sumSrc":"Oyez","by":{"1":"20"}},{"t":"case","label":"Hanover Am. Ins. Co. v. Tattooed Millionaire Ent., LLC","cite":"974 F.3d 767","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/974/767/","by":{"1":"18, 43"}},{"t":"case","label":"Holley v. Northrop Worldwide Aircraft Servs., Inc.","cite":"835 F.2d 1375","y":1988,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.2d/835/1375/","by":{"1":"38"}},{"t":"case","label":"Jones v. Bock","cite":"549 U.S. 199","y":2007,"id":"2006/05-7058","sc":1,"sum":"The Court ruled unanimously that the Sixth Circuit's rules for exhaustion of administrative remedies were not required by the Prisoner Litigation Reform Act. The opinion by Chief Justice John Roberts held that prisoners bring civil rights lawsuits do not need to demonstrate that they have already exhausted all administrative remedies.","sumSrc":"Oyez","by":{"1":"7, 36"}},{"t":"case","label":"K&T Enters. v. Zurich Ins. Co.","cite":"97 F.3d 171","y":1996,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/97/171/","by":{"1":"25"}},{"t":"case","label":"Keepseagle v. Perdue","cite":"856 F.3d 1039","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/856/1039/","by":{"1":"27"}},{"t":"case","label":"Merck Sharp & Dohme Corp. v. Albrecht","cite":"139 S. Ct. 1668","y":2019,"id":"2018/17-290","sc":1,"sum":"“Clear evidence” that the FDA would not have approved a change to a drug’s label—thus pre-empting a state-law failure-to-warn claim—is evidence showing that the drug manufacturer fully informed the FDA of the justifications for the warning required by state law and that the FDA, in turn, informed the drug manufacturer that the FDA would not approve a change to the drug’s label to include that warning; the question of agency disapproval is primarily one of law for a judge to decide.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"17"}},{"t":"case","label":"N.Y. Marine & Gen. Ins. Co. v. Cont’l Cement Co.","cite":"761 F.3d 830","y":2014,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/761/830/","op":1,"by":{"1":"44"}},{"t":"case","label":"Pavey v. Conley","cite":"544 F.3d 739","y":2008,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/544/739/","by":{"1":"20"}},{"t":"case","label":"Peralta v. Dillard","cite":"744 F.3d 1076","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/744/1076/","by":{"1":"27"}},{"t":"case","label":"Pullman-Standard v. Swint","cite":"456 U.S. 273","y":1982,"id":"1981/80-1190","sc":1,"op":1,"sum":"The Court of Appeals erred in the course of its review of the District Court's judgment.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"43"}},{"t":"case","label":"Ross v. Blake","cite":"578 U.S. 632","y":2016,"id":"2015/15-339","sc":1,"sum":"The Court determined that the Prison Litigation Reform Act’s requirement to exhaust administrative remedies does not have a “special circumstances” exception.","sumSrc":"Oyez","by":{"1":"6-8, 10-11, 40","2":"19"}},{"t":"case","label":"Teva Pharms. USA, Inc. v. Sandoz, Inc.","cite":"574 U.S. 318","y":2015,"id":"2014/13-854","sc":1,"op":1,"sum":"The Court ruled that a federal appellate court can only overturn a district court’s finding of fact if those findings were determined to be “clearly erroneous.”","sumSrc":"Oyez","by":{"1":"30","2":"17"}},{"t":"case","label":"U.S. Bank N.A. v. Vill. at Lakeridge, LLC","cite":"138 S. Ct. 960","y":2018,"id":"2017/15-1509","sc":1,"sum":"The Court held that a designation of non-statutory insider status is reviewable under the standard of clear error because the \"mixed question\" of law and fact at issue is primarily factual.","sumSrc":"Oyez","by":{"1":"42"}},{"t":"case","label":"United States v. Palomar-Santiago","cite":"141 S. Ct. 1615","y":2021,"id":"2020/20-437","sc":1,"sum":"Each of 8 U. S. C. §1326(d)’s statutory requirements for bringing a collateral attack on a prior deportation order is mandatory.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"23"}},{"t":"case","label":"Woodhouse v. Duncan","cite":"741 F. App’x 177","y":2018,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/741/177/","by":{"1":"20"}},{"t":"case","label":"Yakus v. United States","cite":"321 U.S. 414","y":1944,"id":"1940-1955/321us414","sc":1,"sum":"The Supreme Court held that Congress sufficiently regulated the powers of the Administrator of the Act in such a way as to be a constitutional delegation of legislative power to obtain a particular objective. The Constitution grants Congress the necessary flexibility to perform its legislative function in a variety of ways.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"9"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"1":"7, 9"}},{"t":"rule","label":"Fed. R. Civ. P. 1","url":"https://www.law.cornell.edu/rules/frcp/rule_1","by":{"1":"2, 37-38, 45","2":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 12","url":"https://www.law.cornell.edu/rules/frcp/rule_12","subs":["(f)"],"by":{"1":"19"}},{"t":"case","label":"01 Communique Lab’y, Inc. v. Citrix Sys., Inc.","cite":"2017 WL 1065573","y":2017,"court":"N.D. Ohio Mar. 21","by":{"2":"16"}},{"t":"case","label":"Catlin v. United States","cite":"324 U.S. 229","y":1945,"id":"scdb/1944-071","sc":1,"sum":"1. In a proceeding instituted by a petition in the District Court for the condemnation of land under the War Purposes Act of 1917, a \"judgment\" entered upon a declaration of taking filed pursuant to the Declaration of Taking Act of 1931, and a subsequent order denying the landowner's motion to vacate the judgment and to dismiss the petition, held not \"final decisions\" under § 128 of the Judicial Code and therefore …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"4"}},{"t":"case","label":"Christianson v. Colt Indus. Operating Corp.","cite":"486 U.S. 800","y":1988,"id":"1987/87-499","sc":1,"sum":"The principal statutes involved in this case, which arises from a jurisdictional dispute between Courts of Appeals, are 28 U. S. C. § 1295(a)(1)granting the Federal Circuit exclusive jurisdiction over an appeal from a final decision of a federal district court \"if the jurisdiction of that court was based, in whole or in part, on\" 28 U. S. C. § 1338-and § 1338(a), which grants the district courts original …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"Confederated Tribes of Siletz Indians of Or. v. Weyerhaeuser Co.","cite":"2003 WL 24901381","y":2003,"court":"D. Or. July 5","by":{"2":"16"}},{"t":"case","label":"Gelboim v. Bank of Am. Corp.","cite":"574 U.S. 405","y":2015,"id":"2014/13-1174","sc":1,"sum":"The Court ruled that a dismissed claim is immediately appealable if the claim is part of a consolidated action and no final order has been issued concerning all claims in the action.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Hall v. Hall","cite":"138 S. Ct. 1118","y":2018,"id":"2017/16-1150","sc":1,"sum":"The Court decided that when one of multiple cases consolidated under FRCP 42(a) is finally decided, that ruling confers upon the losing party the right to immediate appeal regardless of whether any of the other consolidated cases are still pending.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Hughes Aircraft Co. v. U.S. ex rel. Schumer","cite":"520 U.S. 939","y":1997,"id":"1996/95-1340","sc":1,"sum":"The Court held that, because the 1986 amendment does not apply retroactively to qui tam suits regarding allegedly false claims submitted prior to its enactment, Schumer's action should have been dismissed, as required by the pre-1986 version of the FCA.","sumSrc":"Oyez","by":{"2":"6"}},{"t":"case","label":"Pickard v. Dep’t of Just.","cite":"217 F. Supp. 3d 1081","y":2016,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/217/1081/","by":{"2":"16"}},{"t":"rule","label":"Fed. R. Civ. P. 54","url":"https://www.law.cornell.edu/rules/frcp/rule_54","subs":["(b)"],"by":{"2":"4"}}]};